const env = typeof $env !== 'undefined' ? $env : process.env;
const endpoint = String(env.TENDER_PRODUCT_MATCHING_URL || 'http://tender-api:8000/product-matching/from-documents').trim();
const apiKey = String(env.TENDER_PYTHON_API_KEY || '').trim();
const allItems = $input.all();

let tenderName = '';
for (const item of allItems) {
  tenderName ||= String(item.json?.tenderName || item.json?.chatInput || '').trim();
}
tenderName ||= 'documents';

const form = new FormData();
form.append('tender_name', tenderName);

let fileCount = 0;
for (let itemIndex = 0; itemIndex < allItems.length; itemIndex++) {
  const item = allItems[itemIndex];
  const binaries = item.binary || {};
  for (const [propertyName, binary] of Object.entries(binaries)) {
    const buffer = await this.helpers.getBinaryDataBuffer(itemIndex, propertyName);
    const fileName = String(binary.fileName || propertyName || `document_${fileCount + 1}`);
    const mimeType = String(binary.mimeType || 'application/octet-stream');
    form.append('files', new Blob([buffer], { type: mimeType }), fileName);
    fileCount++;
  }
}

if (!fileCount) {
  return [{
    json: {
      output: 'Прикрепите хотя бы один файл PDF, Word или Excel и отправьте сообщение еще раз.',
      status: 'no_files'
    }
  }];
}

const headers = {};
if (apiKey) headers['X-API-Key'] = apiKey;

const response = await fetch(endpoint, {
  method: 'POST',
  headers,
  body: form,
});

if (!response.ok) {
  const text = await response.text();
  throw new Error(`Tender Worker returned HTTP ${response.status}: ${text.slice(0, 2000)}`);
}

const arrayBuffer = await response.arrayBuffer();
const outputName = `autopodbor_${(tenderName || 'documents').replace(/[^a-z0-9а-яё_-]+/gi, '_').slice(0, 80) || 'documents'}.xlsx`;
const data = await this.helpers.prepareBinaryData(
  Buffer.from(arrayBuffer),
  outputName,
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
);

return [{
  json: {
    output: `Готово. Сформирован файл: ${outputName}`,
    status: 'completed',
    tenderName,
    uploadedFiles: fileCount,
    fileName: outputName,
  },
  binary: { data },
}];
